import{_ as r,C as n,o as i,c as s,aj as e,E as o}from"./framework.js";const b=JSON.parse('{"title":"Basic · General Tab | Settings / Basic | Admin CMS","description":"This tab configures public site identity, preview Base URL, HTTPS/SPA behavior, multilingual culture, and import / export of full site packages.","frontmatter":{"title":"Basic · General Tab | Settings / Basic | Admin CMS","description":"This tab configures public site identity, preview Base URL, HTTPS/SPA behavior, multilingual culture, and import / export of full site packages.","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/settings/basic/general.html"}]]},"headers":[],"relativePath":"cms/settings/basic/general.md","filePath":"en/cms/settings/basic/general.md","lastUpdated":1781010536000}'),l={name:"cms/settings/basic/general.md"};function d(g,t,c,u,h,p){const a=n("DocImage");return i(),s("div",null,[t[0]||(t[0]=e('<h1 id="basic-·-general-tab" tabindex="-1">Basic · General Tab <a class="header-anchor" href="#basic-·-general-tab" aria-label="Permalink to &quot;Basic · General Tab&quot;">​</a></h1><blockquote><p>Tab: <strong>General</strong> · <code>name=basic</code><br> Deep link: <code>/_Admin/system/settings?SiteId={siteGuid}&amp;name=basic</code></p></blockquote><p>This tab configures <strong>public site identity</strong>, <strong>preview Base URL</strong>, HTTPS/SPA behavior, <strong>multilingual</strong> culture, and <strong>import / export</strong> of full site packages.</p>',3)),o(a,{src:"/cms/settings/settings-basic-general.png",alt:"General tab",width:"1120"}),t[1]||(t[1]=e('<h2 id="site-information" tabindex="-1">Site Information <a class="header-anchor" href="#site-information" aria-label="Permalink to &quot;Site Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Display name</strong></td><td>Site name in admin and control panel (<code>displayName</code>)</td></tr><tr><td><strong>Base URL</strong></td><td>Base for preview and absolute links (<code>previewUrl</code>); should match the primary domain in <a href="./../domains.html">Domains</a> or an alias</td></tr><tr><td><strong>Force SSL</strong></td><td>Redirect HTTP to HTTPS. If CDN/proxy already terminates HTTPS and you see <strong>too many redirects</strong>, turn this off</td></tr><tr><td><strong>SPA</strong></td><td><strong>404 redirects to home page</strong> for SPA front-end routing</td></tr></tbody></table><h2 id="multilingual" tabindex="-1">Multilingual <a class="header-anchor" href="#multilingual" aria-label="Permalink to &quot;Multilingual&quot;">​</a></h2><p>Enable with the <strong>Multilingual</strong> panel (<code>enableMultilingual</code>). When disabled on save, cultures collapse to <strong>default language</strong> only and path-mode options turn off.</p>',4)),o(a,{src:"/cms/settings/settings-basic-multilingual.png",alt:"Multilingual configuration",width:"1120"}),t[2]||(t[2]=e('<h3 id="language-list" tabindex="-1">Language List <a class="header-anchor" href="#language-list" aria-label="Permalink to &quot;Language List&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td><strong>Add</strong></td><td>Pick from built-in cultures or <strong>enter custom</strong> two-letter code (e.g. <code>en</code>, <code>zh</code>); invalid format shows a warning</td></tr><tr><td><strong>Display name</strong></td><td>Label per language (e.g. “Simplified Chinese”)</td></tr><tr><td><strong>Delete</strong></td><td>Allowed when at least one language remains</td></tr></tbody></table><h3 id="default-language" tabindex="-1">Default Language <a class="header-anchor" href="#default-language" aria-label="Permalink to &quot;Default Language&quot;">​</a></h3><p><strong>Default language</strong> lists only current cultures; deleting the default picks the first remaining item.</p><h3 id="path-mode" tabindex="-1">Path Mode <a class="header-anchor" href="#path-mode" aria-label="Permalink to &quot;Path Mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>Parameter mode</strong></td><td>Language via query parameter, etc. (<code>enableSitePath=false</code>)</td></tr><tr><td><strong>Route mode</strong></td><td>Language as URL path prefix (<code>enableSitePath=true</code>)</td></tr></tbody></table><p>In route mode, configure <strong>default language prefix</strong>: whether default-language URLs include a language prefix.</p><h3 id="other-switches" tabindex="-1">Other Switches <a class="header-anchor" href="#other-switches" aria-label="Permalink to &quot;Other Switches&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Switch</th><th>Description</th></tr></thead><tbody><tr><td><strong>Auto-detect language</strong></td><td>Pick culture from visitor <code>Accept-Language</code>, etc.</td></tr><tr><td><strong>HrefLang</strong></td><td>Emit <code>hreflang</code> links for search engines</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Distinction from SPA multilingual</p><p>This page configures <strong>Kooboo site culture</strong> (page/content multilingual and URL rules). <a href="./../../development/spa-multilingual.html">Development -&gt; SPA multilingual</a> manages <strong>front-end SPA language JSON</strong>—different data sources; do not mix them.</p></div><p>Scripts and templates often use <a href="/kb-docs/api/label/">k.label</a> per culture.</p><h2 id="import-export-site-package" tabindex="-1">Import / Export Site Package <a class="header-anchor" href="#import-export-site-package" aria-label="Permalink to &quot;Import / Export Site Package&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><strong>Import package</strong></td><td><code>site·edit</code></td><td>Upload Kooboo site package (extension per product <code>importAccept</code>); merges into current site</td></tr><tr><td><strong>Export site</strong></td><td><code>site·export</code></td><td>Export dialog, then download site package</td></tr></tbody></table><p>After import, the page <strong>reloads site</strong> config. Export differs from <a href="./../../operations/sync.html">Operations sync</a> push/pull.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./">Basic Settings overview</a></li><li><a href="./access.html">Access Control</a></li><li><a href="./../domains.html">Domains</a></li></ul>',16))])}const f=r(l,[["render",d]]);export{b as __pageData,f as default};
